async(page)=>{
 const checks=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-r1m/';
 const assert=(x,m)=>{if(!x)throw Error(m)};
 const role=async r=>{await page.locator(`[data-role=${r}]`).first().click();if(r==='dispatch')await page.locator('[data-dispatch-tab=orders]').click();};
 const nav=async n=>{await page.locator(`[data-nav=${n}]`).click();if(n==='dispatch')await page.locator('[data-dispatch-tab=orders]').click();};
 const open=async a=>page.locator(`[data-action=${a}]`).first().click();
 const fill=async p=>{for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(typeof v==='boolean'){await el.setChecked(v)}else if(await el.evaluate(x=>x.tagName)==='SELECT'){await el.selectOption(String(v))}else await el.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'})};
 const act=async(a,p={})=>{await open(a);await fill(p);await submit()};
 const bad=async(a,p,match)=>{await open(a);await fill(p);await page.locator('#action-form [type=submit]').click();await page.waitForTimeout(350);assert((await page.locator('#form-error').innerText()).includes(match),a+' guard missing');await page.locator('[data-close]').first().click();if(await page.locator('#dialog').isVisible())await page.locator('[data-close]').first().click()};
 const db=async()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 const reset=async()=>{await role('dispatch');await open('qa');await act('reset');await role('dispatch')};
 const approve=async id=>{await nav('partners');await page.locator(`[data-partner=${id}]`).click();await act('partnerApprove',{evidence:'DEMO-QUALIFIED',qualified:true,matched:true})};
 const parcel=async()=>{await nav('dispatch');await act('bookingDraft',{evidence:'DEMO-QUOTE',matched:true});await act('bookingContact',{evidence:'DEMO-CONTACT'});await act('bookingConfirm',{externalNo:'DEMO-TRACK-01',evidence:'DEMO-CONFIRM'});await act('bookingReady');await role('warehouse');await act('bookingHandover',{receiver:'Srey · 演示',evidence:'DEMO-HANDOVER',packaging:true});await role('dispatch')};
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1100});await reset();
 await open('partnerOffer');assert(await page.locator('[name=partnerId] option:disabled').count()===1,'pending partner selectable');await page.locator('[data-close]').first().click();
 await approve('P01');await page.screenshot({path:base+'partner-onboarding.png',fullPage:true});await nav('dispatch');await act('partnerOffer',{evidence:'DEMO-PARTNER-QUOTE',matched:true});
 await role('driver');assert(!await page.locator('[data-action=accept]').count(),'self driver sees partner task');await role('partnerDriver');await bad('accept',{},'实际可用');await act('accept',{available:true,cargoConfirmed:true});await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'partner mobile overflow');await page.screenshot({path:base+'partner-driver-mobile.png',fullPage:true});await page.setViewportSize({width:1440,height:1100});
 await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('partnerDriver');await act('pickup',{evidence:'DEMO-PICKUP'});await act('depart');await act('report',{proof:'DEMO-CASH'});await act('deliver',{receiver:'演示收货人',evidence:'DEMO-POD'});assert((await db()).payables.length===1,'partner payable missing');
 await role('finance');await act('verify',{evidence:'DEMO-CASH-VERIFY'});await role('partnerDriver');await act('remit',{evidence:'DEMO-REMIT'});await role('finance');await act('reconcile',{evidence:'DEMO-REMIT-CHECK'});checks.push('合作准入、派单、角色隔离、接单双确认、交接、签收、运费核验与交款');
 await nav('payables');await act('payableDispute',{evidence:'DEMO-DIFF'});assert(!await page.locator('[data-action=payablePay]').count(),'dispute allows pay');await act('payableVerify',{evidence:'DEMO-RESOLVE'});await act('payablePay',{amount:8,evidence:'DEMO-PAY-1'});await bad('payablePay',{amount:1,evidence:'DEMO-PAY-1'},'已登记');await act('payablePay',{evidence:'DEMO-PAY-2'});await act('payableReverse',{evidence:'DEMO-REVERSAL'});await act('payableVerify',{evidence:'DEMO-RECHECK'});await act('payablePay',{evidence:'DEMO-PAY-3'});assert((await db()).payables[0].status==='paid','payable incomplete');await page.screenshot({path:base+'payables-complete.png',fullPage:true});checks.push('应付争议、核对、部分付款、凭证防重、冲正及重新核对');
 await role('dispatch');await nav('partners');await act('partnerPause',{reason:'演示暂停',continueExisting:true});await role('partnerDriver');assert(await page.locator('[data-order]').count()>0,'authorized history hidden');await role('dispatch');await nav('partners');await act('partnerExit',{reason:'演示退出',continueExisting:false});await role('partnerDriver');assert(await page.locator('[data-order]').count()===0,'revoked partner sees task');checks.push('暂停保留授权任务、退出撤销司机访问');
 await reset();await approve('P01');await nav('dispatch');await act('partnerOffer',{evidence:'DEMO-REJECT-QUOTE',matched:true});await role('partnerDriver');await act('reject',{reason:'演示窗口冲突'});await role('dispatch');await act('partnerOffer',{evidence:'DEMO-RETURN-QUOTE',matched:true});await role('partnerDriver');await act('accept',{available:true,cargoConfirmed:true});await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('partnerDriver');await act('pickup',{evidence:'DEMO-HO'});await act('depart');await act('report',{proof:'DEMO-PARTIAL-CASH'});await act('deliver',{count:2,receiver:'演示客户',evidence:'DEMO-PARTIAL-POD'});await role('dispatch');await act('authorizeReturn',{reason:'剩余两件回仓，容量与原承诺已复核'});await role('partnerDriver');await act('returnArrived');await role('warehouse');await bad('receiveReturn',{count:1,evidence:'DEMO-RETURN'},'件数');await act('receiveReturn',{count:2,evidence:'DEMO-RETURN'});assert((await db()).orders[0].status==='closed_exception','partner return incomplete');await page.screenshot({path:base+'partner-returned.png',fullPage:true});checks.push('合作司机拒单重派、部分签收、授权返仓、差异阻断与仓库点收');
 await reset();await approve('P02');await parcel();assert((await db()).orders[0].vehicle===null,'parcel has virtual vehicle');
 const local=offset=>new Date(Date.now()+7*3600000+offset).toISOString().slice(0,16);
 await act('bookingEvent',{eventId:'DEMO-UNKNOWN',rawStatus:'unknown_scan',evidence:'DEMO-RAW'});assert((await db()).orders[0].booking.status==='handed_over','unknown status advanced');
 const transit={eventId:'DEMO-TRANSIT',rawStatus:'in_transit',occurredAt:local(-180000),evidence:'DEMO-RAW'};await act('bookingEvent',transit);await act('bookingEvent',transit);
 await act('bookingEvent',{eventId:'DEMO-DELIVER',rawStatus:'delivered',occurredAt:local(-60000),evidence:'DEMO-POD-REPORT'});assert((await db()).orders[0].status==='in_transit','report auto completed');await act('bookingEvent',{eventId:'DEMO-LATE',rawStatus:'in_transit',occurredAt:local(-240000),evidence:'DEMO-LATE-REPORT'});await bad('bookingVerify',{count:3,evidence:'DEMO-POD',confirmed:true},'完整件数');await act('bookingVerify',{evidence:'DEMO-POD',confirmed:true});assert((await db()).orders[0].collection==='due','POD altered finance');await page.screenshot({path:base+'parcel-verified.png',fullPage:true});await role('finance');await nav('payables');await act('payableVerify',{evidence:'DEMO-CARRIER-CHECK'});await act('payablePay',{evidence:'DEMO-CARRIER-PAY'});checks.push('人工联系、承运确认、件级交接、未知/重复/乱序事件、签收核验、快递应付');
 await reset();await approve('P02');await nav('dispatch');await act('bookingDraft',{evidence:'DEMO-Q',matched:true});await act('bookingContact',{evidence:'DEMO-CONTACT-UNKNOWN'});await act('bookingCancel',{reason:'联系结果不明，确认取消'});assert(!await page.locator('[data-action=offer]').count(),'pending cancel allows dispatch');await act('bookingCancelConfirm',{noCustody:true,evidence:'DEMO-CANCEL'});assert(await page.locator('[data-action=offer]').count()===1,'confirmed cancellation cannot dispatch');checks.push('联系结果未知、取消待确认阻断改派、取消确认释放');
 await parcel();await act('bookingException',{reason:'演示拒收',owner:'演示调度员',evidence:'DEMO-EXCEPTION'});await act('bookingReturnConfirm',{evidence:'DEMO-RETURN-CONFIRMED',confirmed:true});await act('bookingReturnArrived',{evidence:'DEMO-ARRIVAL'});await role('warehouse');await bad('bookingReturnReceive',{count:3,evidence:'DEMO-RETURN'},'件数');await act('bookingReturnReceive',{evidence:'DEMO-RETURN'});assert((await db()).orders[0].status==='closed_exception','return not closed');await page.screenshot({path:base+'parcel-returned.png',fullPage:true});checks.push('异常责任与期限、承运退回确认、到仓、点收差异阻断及结案');
 await role('dispatch');await nav('partners');await act('partnerRegister',{name:'测试登记承运方 · 演示',contact:'演示联系人',type:'PARCEL_CARRIER'});assert((await db()).partners.at(-1).status==='pending','registered bypass approval');checks.push('合作方登记保持待核验');
 await page.setViewportSize({width:1280,height:900});for(const n of ['partners','bookings']){await nav(n);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),n+' overflow')};await role('finance');await nav('payables');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'payable overflow');await page.reload();assert((await db()).orders[0].status==='closed_exception','reload lost progress');checks.push('1280px 工作台布局与会话刷新保留');
 return {browser:'PASS',checks};
}
